// ==== NFV:THEORY BEGIN (stage 1a, frozen) ====
// Library theory for the Python built-in `int` applied to a float (modeled as `real`).

// "int([x]) -> integer ... Convert a number or string to an integer ...
//  If x is a number, return x.__int__().  For floating-point numbers, this truncates towards zero."
// Floats are modeled as exact `real`s (no NaN/inf), so int(x) is x rounded towards zero.
function PyIntOfFloat(x: real): int
{
  if x >= 0.0 then x.Floor else -((-x).Floor)
}

// Truncation towards zero: |PyIntOfFloat(x)| <= |x| < |PyIntOfFloat(x)| + 1, and the sign of x is kept.
lemma PyIntOfFloatTruncates(x: real)
  ensures x >= 0.0 ==> 0 <= PyIntOfFloat(x)
                       && PyIntOfFloat(x) as real <= x
                       && x < PyIntOfFloat(x) as real + 1.0
  ensures x < 0.0 ==> PyIntOfFloat(x) <= 0
                      && x <= PyIntOfFloat(x) as real
                      && PyIntOfFloat(x) as real - 1.0 < x
{
}
// ==== NFV:THEORY END ====
