// src: source.py:1 | def truncate_number(number: float) -> float:
method truncate_number(number: real) returns (return_value: real)
  // synth: frozen precondition (stage 1b)
  requires number > 0.0
  // synth: witness (refutation)
  requires number == 3.0
  // synth: frozen negated postcondition (refutation)
  ensures !((0.0 <= return_value && return_value < 1.0))
{
  // src: source.py:10 | integer_part = int(number)
  var integer_part: int := PyIntOfFloat(number);
  // src: source.py:11 | decimal_part = number - integer_part
  var decimal_part: real := number - integer_part as real;
  // src: source.py:13 | return decimal_part + 1
  return_value := decimal_part + 1.0;
  return;
}
